export function repairWritesPerSec(readQps, replicasChecked, stalePermille) {
  return (readQps * replicasChecked * stalePermille) / 1000;
}

export function repairSharePermille(readQps, replicasChecked, stalePermille, writeQps) {
  return (repairWritesPerSec(readQps, replicasChecked, stalePermille) * 1000) / writeQps;
}

