exercises.solution:
export function fullSyncBytesPerDay(dataBytes, replicas, syncsPerDay) {
  return dataBytes * (replicas - 1) * syncsPerDay;
}

export function merkleSyncBytesPerDay(dataBytes, replicas, syncsPerDay, divergentPermille) {
  return (fullSyncBytesPerDay(dataBytes, replicas, syncsPerDay) * divergentPermille) / 1000;
}

