exercises.solution:
export function nodesLeftAfterZoneLoss(nodes, zones) {
  return nodes - Math.ceil(nodes / zones);
}

export function survivesZoneLoss(nodes, zones) {
  return nodesLeftAfterZoneLoss(nodes, zones) >= Math.floor(nodes / 2) + 1;
}
